import React, { useState, useEffect, useRef } from 'react';

/**
 * Compteur animé : le nombre monte de 0 jusqu'à `value`.
 * Usage : <AnimatedCounter value={1250} duration={1200} suffix=" FCFA" />
 *
 * Props:
 *   value     : nombre cible
 *   duration  : durée en ms (défaut 1200)
 *   decimals  : nombre de décimales (défaut 0)
 *   prefix / suffix : texte avant / après
 *   separator : séparateur de milliers (défaut espace insécable)
 */
const AnimatedCounter = ({
  value = 0,
  duration = 1200,
  decimals = 0,
  prefix = '',
  suffix = '',
  separator = ' ',
  style,
  className,
}) => {
  const [display, setDisplay] = useState(0);
  const rafRef = useRef(null);
  const startRef = useRef(null);
  const fromRef = useRef(0);

  useEffect(() => {
    const target = Number(value) || 0;
    fromRef.current = display;
    startRef.current = null;

    const ease = (t) => 1 - Math.pow(1 - t, 3); // easeOutCubic

    const step = (ts) => {
      if (startRef.current === null) startRef.current = ts;
      const progress = Math.min((ts - startRef.current) / duration, 1);
      const current = fromRef.current + (target - fromRef.current) * ease(progress);
      setDisplay(current);
      if (progress < 1) {
        rafRef.current = requestAnimationFrame(step);
      } else {
        setDisplay(target);
      }
    };

    rafRef.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(rafRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, duration]);

  const formatted = display
    .toFixed(decimals)
    .replace(/\B(?=(\d{3})+(?!\d))/g, separator);

  return (
    <span className={className} style={style}>
      {prefix}{formatted}{suffix}
    </span>
  );
};

export default AnimatedCounter;
